  (7, 3, '11 Exit', 'full game', 'Finish the game using only 11 exits.'),
  (8, 1, 'Any%', 'full game', 'Reach the credits as fast as possible.'),
  (8, 2, '100%', 'full game', 'Collect every item, heart piece, and Skulltula token.'),
  (8, 3, 'Glitchless Any%', 'full game', 'Beat the game without glitches.'),
  (9, 1, 'Inbounds', 'full game', 'No out-of-bounds glitches. Timing excludes loads.'),
  (9, 2, 'Out of Bounds', 'full game', 'Out-of-bounds glitches allowed. Timing excludes loads.'),
  (9, 3, 'Glitchless', 'full game', 'No glitches of any kind.'),
  (10, 1, 'Any% Random Seed Glitchless', 'full game', 'Defeat the Ender Dragon on a random seed without glitches. Video required.'),
